export const run = mutation({
  args: {},
  handler: async (ctx) => {
    const existing = await ctx.db.query('movies').collect();
    const existingTokens = new Set(existing.map(m => m.token));

    // Insert only new movies (skip existing by token)
    let inserted = 0;
    for (const movie of MOVIES) {
      if (!movie || !movie.token) continue;
      if (!existingTokens.has(movie.token)) {
        await ctx.db.insert('movies', movie);
        inserted++;
      }
    }

    const existingPlans = await ctx.db.query('plans').collect();
    for (const plan of existingPlans) {
      await ctx.db.delete(plan._id);
    }
    for (const plan of PLANS) {
      await ctx.db.insert('plans', plan);
    }

    return {
      movies: { inserted, existing: existing.length, total: MOVIES.length },
      plans: { replaced: PLANS.length },
    };
  },
});
